with with_dims as (select e.id, e.customer_id, e.balance, e.opened_date, e.status, d.country, d.age, d.signup_date from accounts e inner join customers d on e.customer_id = d.id), with_windows as (select id, customer_id, opened_date, status, country, sum(balance) over (partition by status order by age, id rows between unbounded preceding and current row) as cumulative_balance, row_number() over w_part as event_seq, ntile(3) over (order by balance desc, id) as balance_bucket from with_dims window w_part as (partition by customer_id order by balance desc, id)), not_flagged as (select s.* from with_windows s where not exists (select 1 from transactions c where c.account_id = s.id and c.account_id in (6, 26, 29))), latest_match as (select s.*, x.transaction_amount, x.txn_type from not_flagged s join lateral (select c.amount as transaction_amount, c.txn_type from transactions c where c.account_id = s.id order by c.txn_time desc, c.id desc limit 1) x on true), totals as (select date_trunc('week', opened_date) as week_start, case when transaction_amount >= 3600 then 'HIGH' else 'LOW' end as transaction_amount_tier, size(collect_set(status)) as num_status, count(case when status = 'CLOSED' then 1 end) as closed_count from latest_match group by 1, 2 having num_status > 1) select week_start, transaction_amount_tier, num_status, closed_count from totals;
